INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(27801, '2 Corinthians 8:2', '2 Corinthians', 8, 2, '&nbsp;د مصيبت د دې سخت آزمېښت په دوران کښې د هغوئ خوشحالى زياته شوه او د سخت غربت باوجود هم هغوئ د زړۀ د اخلاصه د خپل طرف نه سخاوت وکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27802, '2 Corinthians 8:3', '2 Corinthians', 8, 3, '&nbsp;ځکه زۀ دا ګواهى ورکوم چې هغوئ د خپل وس په مطابق نه، بلکې د خپل وس نه يې هم زيات په خپله خوښه ورکړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27803, '2 Corinthians 8:4', '2 Corinthians', 8, 4, '&nbsp;هغوئ مونږ ته ډېر مِنت وکړو چې، مونږ هم مقدسينو ته د خېرات ورکولو د خِدمت په فضل کښې شريک کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27804, '2 Corinthians 8:5', '2 Corinthians', 8, 5, '&nbsp;خو هغوئ زمونږ د اُميد نه زياته ورکړه وکړه، بلکې خپل زړونه يې اول مالِک ته او بيا يې د خُدائ پاک په مرضۍ مونږ ته وسپارل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27805, '2 Corinthians 8:6', '2 Corinthians', 8, 6, '&nbsp;د دې دپاره مونږ تيطوس ته مِنت وکړو لکه څنګه چې هغۀ دا کار شروع کړے وو، هم هغه شان دې په تاسو کښې هم د خېرات دغه کار پوره کړے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27806, '2 Corinthians 8:7', '2 Corinthians', 8, 7, '&nbsp;نو لکه څنګه چې تاسو په هره خبره کښې، د ايمان او کلام او عِلم او جوش او هغه مينه چې ستاسو مونږ سره ده، په هغې کښې وړاندې شوى يئ نو مونږ غواړو چې تاسو هم هغه شان د خېرات په دې کار کښې هم وړاندې شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27807, '2 Corinthians 8:8', '2 Corinthians', 8, 8, '&nbsp;زۀ د حُکم په طور دا نۀ وايم بلکې د دې دپاره چې زۀ د نورو د جوش مقابل کښې ستاسو د مينې رښتينوالے وآزمائيم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27808, '2 Corinthians 8:9', '2 Corinthians', 8, 9, '&nbsp;ځکه چې تاسو زمونږ د مالِک عيسىٰ مسيح د فضل نه خبر يئ. کۀ څۀ هم چې هغه غنى وو خو هغه ستاسو دپاره غريب شو، د دې دپاره چې د هغۀ د غربت په وسيله تاسو مالدار شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27809, '2 Corinthians 8:10', '2 Corinthians', 8, 10, '&nbsp;نو زۀ په دې باب کښې تاسو ته زما نصيحت کوم چې ستاسو دپاره به دا ښۀ وى، چې هغه کار تر سره کړئ کوم چې مو يو کال مخکښې شروع کړے وو. تير کال تاسو په ورکړه کښې د ټولو نه اول وئ، او دا هم تاسو وئ چې دا کار مو اول شروع کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27810, '2 Corinthians 8:11', '2 Corinthians', 8, 11, '&nbsp;نو اوس دا کار پوره هم کړئ. لکه څنګه چې تاسو اراده کښې چاخ وئ هم هغه شان د وس په مطابق يې پوره هم کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27811, '2 Corinthians 8:12', '2 Corinthians', 8, 12, '&nbsp;ځکه کۀ د ورکولو شوق وى نو خُدائ پاک هديه د هغې په مطابق قبلوى څۀ چې د چا سره وى، نه چې د هغې په مطابق چې د هغۀ سره نۀ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27812, '2 Corinthians 8:13', '2 Corinthians', 8, 13, '&nbsp;زما مطلب دا نۀ دے چې د نورو بوج دې کم شى او ستاسو دې زيات شى، بلکې په کار دے چې دا برابر وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27813, '2 Corinthians 8:14', '2 Corinthians', 8, 14, '&nbsp;دې وخت تاسو سره زيات څۀ دى دا به د هغوئ ضرورت پوره کړى، او کله چې د هغوئ سره زيات شى، نو هغوئ به ستاسو ضرورت پوره کړى، او دغه شان به تاسو کښې برابرے قائم وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27814, '2 Corinthians 8:15', '2 Corinthians', 8, 15, '&nbsp;لکه چې صحيفو کښې ليکلى دى چې، ”چا چې ډېره راټوله کړې وه د هغۀ سره ډېره زياته نۀ وه او چا چې لږه راټوله کړې وه د هغۀ سره کمه نۀ وه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27815, '2 Corinthians 8:16', '2 Corinthians', 8, 16, '&nbsp;خو د خُدائ پاک شُکر دے چې هغۀ د تيطوس په زړۀ کښې ستاسو دپاره هم زما په شان سرګرمى پېدا کړې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27816, '2 Corinthians 8:17', '2 Corinthians', 8, 17, '&nbsp;ځکه چې هغۀ نۀ تش زمونږ خواست ومنلو بلکې هغه د مخکښې نه د زياتې سرګرمۍ سره په خپله مرضۍ تاسو ته درروان دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27817, '2 Corinthians 8:18', '2 Corinthians', 8, 18, '&nbsp;د هغۀ سره مونږ خپل هغه ورور درلېږُو څوک چې په ټولو جماعتونو کښې د زيرى د پېغام ورکولو دپاره مشهور دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27818, '2 Corinthians 8:19', '2 Corinthians', 8, 19, '&nbsp;او نۀ صرف دا بلکې هغه د جماعتونو له خوا نه د دې چندې د رسولو په خِدمت کښې زمونږ د سفر ملګرے مقرر شو، او مونږ دا خِدمت ځکه وکړُو چې د مالِک جلال او زمونږ سرګرمى ښکاره شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27819, '2 Corinthians 8:20', '2 Corinthians', 8, 20, '&nbsp;مونږ په شريکه د دې لوئې هديې د ساتلو خِدمت کوُو د دې دپاره چې په مونږ څوک هم څۀ قسم اِلزام ونۀ لګوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27820, '2 Corinthians 8:21', '2 Corinthians', 8, 21, '&nbsp;نو مونږ ځکه ډېر کوشش کوُو چې داسې منصوبه جوړه کړُو چې هغه نۀ صرف د مالِک خُدائ په نظر کښې ښۀ وى بلکې چې د خلقو په نظر کښې هم ښۀ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27821, '2 Corinthians 8:22', '2 Corinthians', 8, 22, '&nbsp;او مونږ د هغوئ سره خپل بل ورور درلېږو څوک چې مونږ څو ځله وآزمائيلو او په ډېرو خبرو کښې مونږ ته سرګرم ښکاره شو، خو اوس هغه نور هم سرګرم دے ځکه چې هغه په تاسو ډېر باور کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27822, '2 Corinthians 8:23', '2 Corinthians', 8, 23, '&nbsp;کۀ څوک د تيطوس په حقله تپوس وکړى نو هغه ما سره په شريکه ستاسو په خِدمت کښې زما ملګرے دے. او زمونږ د نورو وروڼو په حقله، هغوئ د جماعتونو د طرفه لېږلے شوى دى او مسيح ته جلال ورکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27823, '2 Corinthians 8:24', '2 Corinthians', 8, 24, '&nbsp;نو په دې وجه خپله مينه ورته ثابته کړى چې ټول جماعتونه دا ووينى چې مونږ په تاسو بې‌ځايه فخر نۀ کوُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27824, '2 Corinthians 9:1', '2 Corinthians', 9, 1, '&nbsp;اوس ما دپاره دا ضرورى نۀ ده چې تاسو ته د مقدسينو د چندې په حقله وليکم', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27825, '2 Corinthians 9:2', '2 Corinthians', 9, 2, '&nbsp;ځکه چې زۀ ستاسو د سرګرمۍ نه خبر يم د هغې په وجه د مِکدونيه د خلقو په وړاندې زۀ په تاسو فخر کوم او وايم چې د اخيه خلق د تير کال نه تيار دى. او ستاسو جوش په هغوئ کښې ډېر خلق راوپارول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27826, '2 Corinthians 9:3', '2 Corinthians', 9, 3, '&nbsp;خو زۀ دا وروڼه درلېږم د دې دپاره چې ستاسو په حقله مونږ کوم فخر کوُو، هغه بې‌مقصده پاتې نۀ شى، بلکې تاسو هغه شان تيار شئ څنګه چې ما هغوئ ته وينا کړې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27827, '2 Corinthians 9:4', '2 Corinthians', 9, 4, '&nbsp;ځکه چې کۀ ما سره د مِکدونيه نه څۀ خلق راشى او هغوئ وګورى چې تاسو تيار نۀ يئ نو مونږ به شرمنده شُو ځکه چې مونږ په تاسو باور کړے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27828, '2 Corinthians 9:5', '2 Corinthians', 9, 5, '&nbsp;نو ما دا خبره ضرورى وګڼله چې په دې وروڼو زور راوړم چې اول کورنتيانو ته لاړ شى او د هغه چندې د مخکښې نه بندوبست وکړى د کومې چې تاسو وعده کړې ده، چې دا چنده په خپله خوښه راجمع کړئ نه چې په زبردستۍ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27829, '2 Corinthians 9:6', '2 Corinthians', 9, 6, '&nbsp;خو ياد ساتئ څوک چې لږه کرونده کوى هغه به لږه رېبى، او چې څوک زياته کرونده کوى هغه به زياته رېبى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27830, '2 Corinthians 9:7', '2 Corinthians', 9, 7, '&nbsp;تاسو هر يو دې هم هغه هومره ورکړى څومره چې يې په زړۀ کښې دى، او نۀ چې په نۀ زړۀ او نۀ د بل چا په مجبورولو سره ځکه چې خُدائ پاک په خوشحالۍ ورکوونکو سره مينه کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27831, '2 Corinthians 9:8', '2 Corinthians', 9, 8, '&nbsp;او خُدائ پاک کولے شى چې تاسو ته ستاسو د ضرورت په مطابق هر څۀ پرېمانه درکړى او تاسو سره به د نورو د مدد کولو دپاره همېشه هر څۀ ډېر وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27832, '2 Corinthians 9:9', '2 Corinthians', 9, 9, '&nbsp;نو په صحيفو کښې داسې ليکلى دى چې، ”هغۀ خپل خېراتونه مسکينانو ته ورلېږلى دى، د هغۀ صداقت د تل دپاره پاتې کيږى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27833, '2 Corinthians 9:10', '2 Corinthians', 9, 10, '&nbsp;نو خُدائ پاک څوک چې د زميندار دپاره تخم او د خوراک دپاره روټۍ ورکوى، هم هغه به تاسو له هم د کَرلو تخم درکړى او زيات به يې کړى او ستاسو د صداقت فصل به هم زيات کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27834, '2 Corinthians 9:11', '2 Corinthians', 9, 11, '&nbsp;تاسو به په هر يو څيز کښې ډېر شتمن شئ د دې دپاره چې تاسو همېشه په هره موقع کښې سخاوت کولے شئ، او په دې سره به د خُدائ پاک شُکر ګزارى وشى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27835, '2 Corinthians 9:12', '2 Corinthians', 9, 12, '&nbsp;ځکه چې د دې خِدمت په کولو به نۀ تش د مقدسينو ضرورتونه پوره شى بلکې د ډېرو خلقو له خوا به د خُدائ پاک ډېره شُکر ګزارى وشى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27836, '2 Corinthians 9:13', '2 Corinthians', 9, 13, '&nbsp;نو ستاسو د خِدمت په وجه به هغوئ د خُدائ پاک لوئى بيان کړى. نو هغوئ او نورو ټولو ايماندارانو ته به ستاسو سخاوت دا خبره ثابته کړى چې تاسو د مسيح د زيرى تابعدار يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27837, '2 Corinthians 9:14', '2 Corinthians', 9, 14, '&nbsp;نو په دې وجه به هغوئ تاسو ته د زړۀ نه دعا کوى د هغه لوئ فضل په وجه کوم چې خُدائ پاک تاسو ته درکړے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27838, '2 Corinthians 9:15', '2 Corinthians', 9, 15, '&nbsp;د خُدائ پاک د هغه بې‌مثاله برکت دپاره شُکر دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27839, '2 Corinthians 10:1', '2 Corinthians', 10, 1, '&nbsp;زۀ پولوس په خپله تاسو ته د مسيح په عاجزۍ او نرمۍ کښې خواست کوم، خو زۀ ستاسو په مخکښې عاجز يم او پشى شا زړَور يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27840, '2 Corinthians 10:2', '2 Corinthians', 10, 2, '&nbsp;بلکې زۀ تاسو ته دا خواست کوم چې زما د حاضرېدو په وخت ما په سخته رويه مۀ مجبوروئ، لکه د چا چې زما په حقله دا خيال دے چې زمونږ خِدمت د دُنياوى طريقې په مطابق دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27841, '2 Corinthians 10:3', '2 Corinthians', 10, 3, '&nbsp;اګر کۀ مونږ انسانان يو خو زمونږ جنګ د انسانانو په مطابق نۀ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27842, '2 Corinthians 10:4', '2 Corinthians', 10, 4, '&nbsp;ځکه چې زمونږ د جنګ وسلې انسانى نۀ دى بلکې زمونږ وسلې د مضبوطو قلاګانو د نړولو دپاره د خُدائ پاک د قُدرت دى. مونږ پرې هر قسمه غلط بحثونه', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27843, '2 Corinthians 10:5', '2 Corinthians', 10, 5, '&nbsp;او هره هغه کبرژنه خبره چې د خُدائ پاک د عِلم خلاف وى تباه کوُو او په هر يو نافرمانه خيال قبضه کوُو د دې دپاره چې د مسيح تابعدار شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27844, '2 Corinthians 10:6', '2 Corinthians', 10, 6, '&nbsp;کله چې ستاسو فرمانبردارى کامله شى نو بيا مونږ تيار يُو چې د هر قِسم نافرمانۍ سزا ورکړُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27845, '2 Corinthians 10:7', '2 Corinthians', 10, 7, '&nbsp;تاسو صرف ظاهرى څيزونو ته ګورئ. کۀ ستاسو په ځان دا باور وى چې تاسو د مسيح يئ، نو مونږ هم ستاسو په شان د مسيح يُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27846, '2 Corinthians 10:8', '2 Corinthians', 10, 8, '&nbsp;ځکه کۀ زۀ په هغه اختيار څۀ لږ فخر کوم چې ستاسو د جوړولو دپاره ما ته مالِک راکړے دے، نه چې ستاسو د ورانولو دپاره، نو زۀ په داسې کولو پښېمانه نۀ يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27847, '2 Corinthians 10:9', '2 Corinthians', 10, 9, '&nbsp;زۀ د خپلو خطونو په وسيله ستاسو د يرولو کوشش کول نۀ غواړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27848, '2 Corinthians 10:10', '2 Corinthians', 10, 10, '&nbsp;ځکه چې د ځينو خلقو زما په حقله دا سوچ دے چې، د هغۀ خطونه اثرناک او زبردست دى خو چې کله هغه په خپله حاضر وى نو کمزورے وى او د هغۀ تقرير فضول وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27849, '2 Corinthians 10:11', '2 Corinthians', 10, 11, '&nbsp;نو دغه شان خلق دې پوهه شى څۀ چې په خطونو کښې زمونږ ليکل دى نو دغه شان به زمونږ په موجودګۍ کښې هم وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27850, '2 Corinthians 10:12', '2 Corinthians', 10, 12, '&nbsp;ځکه چې مونږ دا جرأت نۀ شُو کولے چې خپل ځانونه په هغه څو کسانو کښې شمېر کړُو يا د هغوئ سره برابر کړُو څوک چې خپله نېک نامى زياتوى، خو کله چې هغوئ په خپله په خپلو کښې د ځانونو اندازه ولګوى او په خپله په خپلو کښې مقابله وکړى نو په هيڅ نۀ پوهيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27851, '2 Corinthians 10:13', '2 Corinthians', 10, 13, '&nbsp;خو بيا هم مونږ به د اندازې نه زيات فخر نۀ کوُو بلکې تر هغه حده، کوم چې خُدائ پاک زمونږ دپاره مقرر کړے دے او چې په کښې تاسو هم راغلى يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27852, '2 Corinthians 10:14', '2 Corinthians', 10, 14, '&nbsp;ځکه چې مونږ خپل ځانونه د هغه حد نه زيات لوئ نۀ ګڼو لکه څنګه چې زمونږ د خِدمت په هغه حد کښې وى، ځکه چې مونږ اولنى کسان وُو چې تاسو ته د مسيح د زيرى په ورکولو در رسېدلى يُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27853, '2 Corinthians 10:15', '2 Corinthians', 10, 15, '&nbsp;او مونږ د نورو په خوارۍ فخر نۀ کوُو خو اُميد کوُو چې ستاسو د ايمان په زياتوالى کښې به زمونږ د کار درجه نوره ډېره زياته شى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27854, '2 Corinthians 10:16', '2 Corinthians', 10, 16, '&nbsp;نو چې مونږ زيرے ستاسو نه نور هم اخوا علاقې ته ورسوو، هغه ځائ ته چرته چې چا خِدمت نۀ دے کړے. نو بيا به مونږ ته د بل په خِدمت د فخر کولو ضرورت نۀ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27855, '2 Corinthians 10:17', '2 Corinthians', 10, 17, '&nbsp;خو، ”هر څوک چې فخر کوى نو هغه دې په مالِک فخر وکړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27856, '2 Corinthians 10:18', '2 Corinthians', 10, 18, '&nbsp;ځکه څوک چې خپل تعريف په خپله کوى هغه د قبلېدو نۀ دے بلکې د چا تعريف چې مالِک په خپله کوى هم هغه د قبلېدو وړ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27857, '2 Corinthians 11:1', '2 Corinthians', 11, 1, '&nbsp;زما خواهش دے چې تاسو ما سره لږ شان بې‌وقوفى وزغمئ. آو، تاسو يې ما سره زغمئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27858, '2 Corinthians 11:2', '2 Corinthians', 11, 2, '&nbsp;زۀ ستاسو دپاره د خُدائ پاک په شان غېرت محسوسوم، ځکه چې ما يو خاوند سره ستاسو د وادۀ کولو او مسيح ته تاسو د يوې پاکې پېغلې په شان د حاضرولو وعده کړې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27859, '2 Corinthians 11:3', '2 Corinthians', 11, 3, '&nbsp;خو زۀ يرېږم چې داسې ونۀ شى لکه څنګه چې مار په خپله چالاکۍ بى‌بى حوا دوکه کړه او ستاسو خيالات هم د هغه خلوص او پاکوالى نه بل خوا شى، کوم چې د مسيح سره په کار دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27860, '2 Corinthians 11:4', '2 Corinthians', 11, 4, '&nbsp;ځکه کۀ تاسو ته څوک هم راشى او هغه د بل عيسىٰ پېغام درکوى، او کۀ څۀ هم چې د هغۀ پېغام او زمونږ کښې فرق هم وى، يا تاسو ته د روحُ القُدس په ځائ څۀ بل روح درکړے شى، يا چې تاسو کوم زيرے قبول کړے دے د هغې نه علاوه بل زيرے درکړى، نو بيا خو هغه تاسو ډېر په خوشحالۍ اورئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27861, '2 Corinthians 11:5', '2 Corinthians', 11, 5, '&nbsp;زۀ خو خپل ځان ستاسو د هغه تش په نامه لويو رسولانو نه کم نۀ ګڼم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27862, '2 Corinthians 11:6', '2 Corinthians', 11, 6, '&nbsp;دا ده چې زۀ په تقرير کولو کښې ماهر نۀ يم خو په عِلم کښې هم کم نۀ يم، مونږ په هر حال او په ټولو خبرو کښې تاسو ته دا وښودل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27863, '2 Corinthians 11:7', '2 Corinthians', 11, 7, '&nbsp;ولې ما دا ګناه وکړه چې مې تاسو ته د خُدائ پاک زيرے مفت در ورسولو او ځان مې لاندې کړو د دې دپاره چې تاسو اوچت شئ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27864, '2 Corinthians 11:8', '2 Corinthians', 11, 8, '&nbsp;ستاسو په خيال چې ما ستاسو د خِدمت دپاره د نورو جماعتونو نه په چنده حاصلولو د هغوئ نه غلا وکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27865, '2 Corinthians 11:9', '2 Corinthians', 11, 9, '&nbsp;او کله چې زۀ تاسو سره وم او حاجتمند وم نو ما په چا بوج وانۀ چولو ځکه چې د مِکدونيه نه وروڼه راغلى وُو او زما حاجت يې پوره کړو او ما په هره خبره کښې په تاسو د بوج اچولو نه ځان ساتلے دے او ساتم به يې هم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27866, '2 Corinthians 11:10', '2 Corinthians', 11, 10, '&nbsp;څنګه چې د مسيح حقيقت په ما کښې دے نو د اخيه په علاقه کښې به هيڅوک ما د دې فخر نه منع نۀ کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27867, '2 Corinthians 11:11', '2 Corinthians', 11, 11, '&nbsp;دا ولې؟ ځکه چې زۀ تاسو سره مينه نۀ کوم؟ خو خُدائ پاک ته پته ده چې زۀ تاسو سره مينه کوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27868, '2 Corinthians 11:12', '2 Corinthians', 11, 12, '&nbsp;خو زۀ به خپل کار لکه د مخکښې په شان جارى ساتم. زما دا کار به هغه خلق د دې نه منع کړى چې څوک چې د دې موقعې پسې ګرځى چې په خپلو کارونو زمونږ د خِدمت په شان فخر وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27869, '2 Corinthians 11:13', '2 Corinthians', 11, 13, '&nbsp;ځکه چې داسې خلق دروغژن رسولان دى او دوکه مار دى او ځانونه يې د مسيح د رسولانو په شان کړى وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27870, '2 Corinthians 11:14', '2 Corinthians', 11, 14, '&nbsp;په دې کښې څۀ حېرانتيا نشته، ځکه چې شېطان هم خپل ځان د يو نُورانى فرښتې په شان جوړوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27871, '2 Corinthians 11:15', '2 Corinthians', 11, 15, '&nbsp;نو بيا کۀ د شېطان خادِمان د صادقانو خادِمانو په شان ځان جوړ کړى نو دا څۀ غټه خبره نۀ ده. خو د هغوئ اَنجام به د هغوئ د کارونو په شان وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27872, '2 Corinthians 11:16', '2 Corinthians', 11, 16, '&nbsp;زۀ بيا وايم چې ما دې څوک بې‌وقوف ونۀ ګڼى خو کۀ ګڼى مې نو د بې‌وقوف په شان مې قبول کړئ نو چې زۀ هم لږ شان فخر وکړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
