(27876, '2 Corinthians 11:20', '2 Corinthians', 11, 20, '&nbsp;ځکه چې تاسو هغوئ هم زغمئ څوک چې تاسو غلامان کوى يا مو داړى، يا مو راګېروى، يا خپل ځان لوئ جوړوى، يا ستاسو په مخ څپېړه درکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27877, '2 Corinthians 11:21', '2 Corinthians', 11, 21, '&nbsp;زۀ په شرم سره وايم چې په دې کولو کښې مونږ ډېر کمزورى وُو. خو کۀ څوک فخر کوى نو زۀ به هم فخر کوم، زۀ دا د يو بې‌وقوف په طور وايم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27878, '2 Corinthians 11:22', '2 Corinthians', 11, 22, '&nbsp;ولې هغوئ عبرانيان دى؟ نو زۀ هم يم. ولې هغوئ بنى اِسرائيل دى؟ نو زۀ هم يم. ولې هغوئ د اِبراهيم د نسل نه دى؟ نو زۀ هم يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27879, '2 Corinthians 11:23', '2 Corinthians', 11, 23, '&nbsp;ولې هغوئ د مسيح خادِمان دى؟ زما وينا لکه د ليونى په شان ده، خو زۀ د هغوئ نه زيات بهتر يم، په محنت کښې زيات، په قېد کښې زيات، په کوړو خوړلو کښې د حد نه زيات، او څو څو ځله د مرګ سره مخامخ شوے يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27880, '2 Corinthians 11:24', '2 Corinthians', 11, 24, '&nbsp;ما د يهوديانو نه پينځۀ ځله يو کم څلوېښت کوړې وخوړلې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27881, '2 Corinthians 11:25', '2 Corinthians', 11, 25, '&nbsp;درې ځله زۀ په چُوکو ووهلے شوم، يو ځلې سنګسار کړے شوم، درې ځلې راباندې د اوبو جهازونه تباه شول او يوه شپه او ورځ سمندر په مخه کړے وم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27882, '2 Corinthians 11:26', '2 Corinthians', 11, 26, '&nbsp;زۀ څو څو ځله په سفر کښې په مختلفو خطرو کښې لکه د دريابونو، د ډاکوانو، د خپل قوم، د غېر‌يهوديانو، د ښار، د بيابان، د سمندر، د دروغژنو وروڼو او خوېندو په خطرو کښې پاتې شوے يم،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27883, '2 Corinthians 11:27', '2 Corinthians', 11, 27, '&nbsp;د سخت محنت او د زيات مشقت په وجه څو څو شپې شوګيره شوے يم. څو څو ځله په لوږو او تندو نارنهور ګرځېدلے يم، څو څو ځله د جامو د کمى په وجه د يخنۍ نه کوکله شوے يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27884, '2 Corinthians 11:28', '2 Corinthians', 11, 28, '&nbsp;د دې خبرو نه علاوه، چې په ما کوم د روزانه غم دے هغه د ټولو جماعتونو دپاره زما په زړۀ کښې سوچ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27885, '2 Corinthians 11:29', '2 Corinthians', 11, 29, '&nbsp;د هغوئ په کمزورتياو زۀ کمزورے کېږم نه څۀ؟ د هغوئ په تيندک خوړلو زما زړۀ نۀ خوږيږى څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27886, '2 Corinthians 11:30', '2 Corinthians', 11, 30, '&nbsp;کۀ فخر کول ضرورى وى نو په کار دے چې زۀ په هغه څيزونو فخر وکړم چې زما کمزورۍ ښکاره کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27887, '2 Corinthians 11:31', '2 Corinthians', 11, 31, '&nbsp;د مالِک عيسىٰ د خُدائ پاک او پلار حمد و ثنا دې همېشه وى، هغه خبر دے چې زۀ دروغ نۀ وايم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27888, '2 Corinthians 11:32', '2 Corinthians', 11, 32, '&nbsp;چې زۀ په دمشق کښې وم نو د ارِتاس بادشاه ګورنر د ټول ښار نه چاپېره څوکۍ کښېنولې وه چې ما ګرفتار کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27889, '2 Corinthians 11:33', '2 Corinthians', 11, 33, '&nbsp;خو زۀ د ښار د دېوال د کړکۍ نه په ټوکرۍ کښې کوز کړے شوم او د هغۀ د پنجې نه بچ شوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27890, '2 Corinthians 12:1', '2 Corinthians', 12, 1, '&nbsp;ما ته فخر کول ضرورى دى، اګر کۀ دا فائده مند نۀ دى خو زۀ به د مالِک د روياګانو او د مکاشفې ذکر وکړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27891, '2 Corinthians 12:2', '2 Corinthians', 12, 2, '&nbsp;زۀ په مسيح کښې يو سړے پېژنم څوک چې څوارلس کاله مخکښې اوچت کړے شو او آخرى آسمان ته پورته کړے شو، خو زۀ خبر نۀ يم چې په وجود کښې وو او کۀ د وجود نه بغېر وو، خُدائ پاک ته پته ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27892, '2 Corinthians 12:3', '2 Corinthians', 12, 3, '&nbsp;او زۀ خبر يم چې دا سړے په وجود کښې يا بې له وجوده وو، هغه ترې زۀ خبر نۀ يم خو خُدائ پاک خبر دے، چې', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27893, '2 Corinthians 12:4', '2 Corinthians', 12, 4, '&nbsp;آسمان ته اوچت کړے شو، او داسې خبرې يې واورېدلې چې د هغې وئيل ناممکنه دى او انسان ته د هغه خبرو بيانول ناروا دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27894, '2 Corinthians 12:5', '2 Corinthians', 12, 5, '&nbsp;زۀ به په داسې سړى خو فخر کوم خو په خپل ځان به بغېر د خپلو کمزوريانو نه فخر ونۀ کړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27895, '2 Corinthians 12:6', '2 Corinthians', 12, 6, '&nbsp;خو کۀ زۀ فخر کول هم غواړم نو بې‌وقوفه به نۀ يم ځکه چې زۀ به رښتيا وايم، خو بيا هم نۀ وايم ځکه چې څوک ما د هغۀ نه زيات ونۀ ګڼى څنګه چې مې وينى يا له ما نه اورى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27896, '2 Corinthians 12:7', '2 Corinthians', 12, 7, '&nbsp;او د دې عجيبه روحانى کشفونو په وجه چې زۀ پرې مغروره نۀ شم زما په بدن کښې د شېطان فرښتې زما د تکليف دپاره ازغے وټومبلو، چې زۀ فخر ونۀ کړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27897, '2 Corinthians 12:8', '2 Corinthians', 12, 8, '&nbsp;د دې په حقله ما مالِک ته درې ځله سوال زارى وکړه چې دا تکليف زما نه لرې کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27898, '2 Corinthians 12:9', '2 Corinthians', 12, 9, '&nbsp;خو هغۀ ما ته وفرمائيل چې، ”زما فضل ستا دپاره کافى دے ځکه چې زما طاقت په کمزورتياو کښې پوره کيږى.“ نو زۀ به په خوشحالۍ په خپلو کمزورتياو فخر وکړم نو چې د مسيح قوت په ما کښې پاتې شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27899, '2 Corinthians 12:10', '2 Corinthians', 12, 10, '&nbsp;په دې وجه زۀ د مسيح د خاطره په کمزورتيا کښې، په بې‌عزتۍ کښې، په سختو کښې، په تکليفونو کښې او په افتونو کښې خوشحاله يم، نو کله چې زۀ کمزورے يم نو بيا هغه وخت هم زورَور يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27900, '2 Corinthians 12:11', '2 Corinthians', 12, 11, '&nbsp;زۀ بې‌وقوف شوم ځکه چې زۀ تاسو مجبور کړم خو تاسو له زما ستائينه کول په کار وو، په وجه د دې چې زۀ هيڅ هم نۀ يم، خو بيا هم د هغه تش په نامه لويو رسولانو نه په هيڅ طور کم نۀ يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');